// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Ensure we don't try to transfer to zero address (OwnableInvalidOwner would revert)
        vm.assume(newOwner != address(0));
        // Ensure the caller is not the zero address (prank fails otherwise)
        vm.assume(newOwner != address(0));
        // Transfer ownership to newOwner
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        // Now newOwner accepts ownership
        vm.prank(newOwner);
        c.acceptOwnership();
        // The owner must be newOwner, not address(0)
        assertTrue(c.owner() == newOwner);
    }
}

